use vstd::prelude::*;

verus! {
    /// Returns the smallest element of a non‐empty vector of i32s.
    /// 
    /// Correctness:
    /// 1) The result is ≤ every element of the vector.
    /// 2) The result equals at least one element of the vector.
    fn smallest_num(nums: &Vec<i32>) -> (min_v: i32)
        requires
            nums.len() > 0,
        ensures
            // (1) min_v is ≤ every element
            forall |j: int| 0 <= j && (j as usize) < nums.len() ==> min_v <= nums[j as usize],
            // (2) min_v equals some element
            exists |j: int| 0 <= j && (j as usize) < nums.len() && min_v == nums[j as usize],
    {
        let n: usize = nums.len();
        // We will scan from index 1 up to n,
        // keeping `min_val` equal to the smallest element seen so far.
        let mut i: usize = 1;
        let mut min_val: i32 = nums[0];
        while i < n
            invariant
                // loop bounds
                1 <= i && i <= n,
                // `min_val` is ≤ every element in nums[0..i)
                forall |j: int| 0 <= j && (j as usize) < i ==> min_val <= nums[j as usize],
                // `min_val` appears in nums[0..i)
                exists |j: int| 0 <= j && (j as usize) < i && min_val == nums[j as usize],
            decreases
                n - i,
        {
            let x: i32 = nums[i];
            if x < min_val {
                // found a new smaller value
                min_val = x;
            }
            i = i + 1;
        }
        min_v = min_val;
    }
}

